import { endpoint, event, fn, invoke, machine, mutation, on, query, tag } from '@hozu/core'
import { z } from 'zod'

export const Note = z.object({
  id: z.string(),
  title: z.string(),
  number: z.number(),
  pinned: z.boolean(),
  createdAt: z.string(),
  sharedWith: z.array(z.string()),
})
// A note another user shared with the signed-in user: only what the recipient may see.
export const SharedNote = z.object({ id: z.string(), title: z.string(), owner: z.string() })
export const ShareName = z.string().regex(/^\s*[A-Za-z]{2,20}\s*$/, 'Use 2–20 letters')
export const NoteKey = z.object({ id: z.string() })
export const NewNote = z.object({
  title: z.string().trim().min(1, 'Write a note').max(60, 'Use at most 60 characters'),
})

export const Draft = event({ payload: z.object({ title: z.string() }) })
export const Add = event({ payload: z.object({ title: z.string() }) })
export const Remove = event({ payload: NoteKey })
export const Pin = event({ payload: NoteKey })
export const Search = event({ payload: z.object({ q: z.string() }) })
export const Edit = event({ payload: NoteKey })
export const CancelEdit = event({ payload: z.object({}) })
export const Save = event({ payload: z.object({ id: z.string(), title: z.string() }) })
export const Archive = event({ payload: NoteKey })
export const Restore = event({ payload: NoteKey })
export const Undo = event({ payload: NoteKey })
export const Select = event({ payload: z.object({ id: z.string(), checked: z.boolean() }) })
export const Share = event({ payload: z.object({ id: z.string(), name: z.string() }) })
export const Unshare = event({ payload: z.object({ id: z.string(), name: z.string() }) })
export const BulkAction = z.enum(['delete', 'archive'])
export const Bulk = event({ payload: z.object({ ids: z.array(z.string()), action: BulkAction }) })

export const notesTag = tag({ param: null })

// The signed-in user's own notes (archived ones included, shared-with-me ones not), in the list page's order.
export const ExportedNote = z.object({
  title: z.string(),
  pinned: z.boolean(),
  archived: z.boolean(),
  createdAt: z.string(),
})
export const exportNotes = endpoint({
  method: 'GET',
  path: '/api/export',
  input: z.object({}),
  output: z.object({ user: z.string(), notes: z.array(ExportedNote) }),
  errors: { Unauthorized: z.object({ message: z.string() }) },
  failed: { Unauthorized: 401 },
})

export const listNotes = query({
  input: z.object({}),
  output: z.array(Note),
  errors: { Unauthorized: z.object({}) },
  scope: 'user',
  freshness: 'request',
  tags: () => [notesTag()],
  runs: 'server',
})

// One of the signed-in user's own notes (archived ones included, shared-with-me ones not), by its number.
export const NoteDetail = Note.extend({ archived: z.boolean() })
export const getNote = query({
  input: z.object({ number: z.string() }),
  output: NoteDetail,
  errors: { Unauthorized: z.object({}), NotFound: z.object({ number: z.string() }) },
  scope: 'user',
  freshness: 'request',
  tags: () => [notesTag()],
  runs: 'server',
})

export const listArchived = query({
  input: z.object({}),
  output: z.array(Note),
  errors: { Unauthorized: z.object({}) },
  scope: 'user',
  freshness: 'request',
  tags: () => [notesTag()],
  runs: 'server',
})

export const addNote = mutation({
  input: NewNote,
  output: Note,
  errors: { Duplicate: z.object({ title: z.string() }), TooMany: z.object({}) },
  invalidates: () => [notesTag()],
  runs: 'server',
})

export const removeNote = mutation({
  input: NoteKey,
  output: NoteKey,
  errors: { NotFound: NoteKey, Archived: NoteKey },
  invalidates: () => [notesTag()],
  runs: 'server',
})

export const togglePin = mutation({
  input: NoteKey,
  output: Note,
  errors: { NotFound: NoteKey, Archived: NoteKey },
  invalidates: () => [notesTag()],
  runs: 'server',
})

export const renameNote = mutation({
  input: z.object({ id: z.string(), title: NewNote.shape.title }),
  output: Note,
  errors: { Duplicate: z.object({ title: z.string() }), NotFound: NoteKey, Archived: NoteKey },
  invalidates: () => [notesTag()],
  runs: 'server',
})

export const archiveNote = mutation({
  input: NoteKey,
  output: Note,
  errors: { NotFound: NoteKey, Archived: NoteKey },
  invalidates: () => [notesTag()],
  runs: 'server',
})

export const restoreNote = mutation({
  input: NoteKey,
  output: Note,
  errors: { NotFound: NoteKey },
  invalidates: () => [notesTag()],
  runs: 'server',
})

// Notes other users shared with the signed-in user (not archived, not deleted).
export const listShared = query({
  input: z.object({}),
  output: z.array(SharedNote),
  errors: { Unauthorized: z.object({}) },
  scope: 'user',
  freshness: 'request',
  tags: () => [notesTag()],
  runs: 'server',
})

export const shareNote = mutation({
  input: z.object({ id: z.string(), name: ShareName }),
  output: Note,
  errors: { NotFound: NoteKey, Archived: NoteKey, Self: z.object({}) },
  invalidates: () => [notesTag()],
  runs: 'server',
})

export const unshareNote = mutation({
  input: z.object({ id: z.string(), name: z.string() }),
  output: Note,
  errors: { NotFound: NoteKey },
  invalidates: () => [notesTag()],
  runs: 'server',
})

// The user's most recent delete, while it can still be undone.
export const lastDeleted = query({
  input: z.object({}),
  output: z.object({ id: z.string(), title: z.string() }).nullable(),
  errors: { Unauthorized: z.object({}) },
  scope: 'user',
  freshness: 'request',
  tags: () => [notesTag()],
  runs: 'server',
})

export const undoRemove = mutation({
  input: NoteKey,
  output: Note,
  errors: { NotFound: NoteKey },
  invalidates: () => [notesTag()],
  runs: 'server',
})

// Bulk actions skip notes that are gone or already archived. A bulk delete cannot be undone.
export const removeNotes = mutation({
  input: z.object({ ids: z.array(z.string()).min(1, 'Select at least one note') }),
  output: z.object({ count: z.number() }),
  invalidates: () => [notesTag()],
  runs: 'server',
})

export const archiveNotes = mutation({
  input: z.object({ ids: z.array(z.string()).min(1, 'Select at least one note') }),
  output: z.object({ count: z.number() }),
  invalidates: () => [notesTag()],
  runs: 'server',
})

const matches = (note: { title: string }, q: string) => note.title.toLowerCase().includes(q.trim().toLowerCase())

export const matching = fn({
  input: z.object({ items: z.array(Note), q: z.string() }),
  output: z.array(Note),
  impl: ({ items, q }) => items.filter((note) => matches(note, q)),
})

export const noneMatch = fn({
  input: z.object({ items: z.array(Note), q: z.string() }),
  output: z.boolean(),
  impl: ({ items, q }) => !items.some((note) => matches(note, q)),
})

// The first `limit` notes the URL filters select, in list order; "Load more" raises the limit.
export const firstMatching = fn({
  input: z.object({ items: z.array(Note), q: z.string(), limit: z.number() }),
  output: z.array(Note),
  impl: ({ items, q, limit }) => items.filter((note) => matches(note, q)).slice(0, limit),
})

export const countMatching = fn({
  input: z.object({ items: z.array(Note), q: z.string() }),
  output: z.number(),
  impl: ({ items, q }) => items.filter((note) => matches(note, q)).length,
})

export const addedOn = fn({
  input: z.object({ at: z.string() }),
  output: z.string(),
  impl: ({ at }) => new Date(at).toISOString().slice(0, 10),
})

export const NOTHING_TO_UNDO = 'There is nothing to undo'
export const DUPLICATE = 'You already have a note with this title'
export const TOO_MANY = 'Too many notes, try again in a minute'
export const NOT_FOUND = 'This note no longer exists'
export const ARCHIVED = 'This note is archived'
export const SHARE_SELF = 'You cannot share with yourself'

export const notesMachine = machine({
  context: z.object({
    draft: z.string(),
    error: z.string().nullable(),
    fields: z.object({ title: z.string().nullable() }),
    target: z.string(),
    shareName: z.string(),
    q: z.string(),
    editing: z.string(),
    editTitle: z.string(),
    editError: z.string().nullable(),
    selected: z.array(z.string()),
  }),
  initialContext: { draft: '', error: null, fields: { title: null }, target: '', shareName: '', q: '', editing: '', editTitle: '', editError: null, selected: [] },
  initial: 'idle',
  states: ({ ctx }) => ({
    idle: {
      on: [
        on(Draft, { target: 'idle', assign: (e) => { ctx.draft = e.title } }),
        on(Add, {
          target: 'adding',
          assign: (e) => {
            ctx.draft = e.title
            ctx.error = null
            ctx.fields = { title: null }
          },
        }),
        on(Remove, { target: 'removing', assign: (e) => { ctx.target = e.id; ctx.error = null; ctx.selected = ctx.selected.filter((id) => id !== e.id) } }),
        on(Pin, { target: 'pinning', assign: (e) => { ctx.target = e.id; ctx.error = null } }),
        on(Archive, { target: 'archiving', assign: (e) => { ctx.target = e.id; ctx.error = null; ctx.selected = ctx.selected.filter((id) => id !== e.id) } }),
        on(Select, { target: 'idle', guard: (e) => e.checked === true, assign: (e) => { ctx.selected = ctx.selected.filter((id) => id !== e.id); ctx.selected.push(e.id) } }),
        on(Select, { target: 'idle', assign: (e) => { ctx.selected = ctx.selected.filter((id) => id !== e.id) } }),
        on(Bulk, { target: 'removingMany', guard: (e) => e.ids.length > 0 && e.action === 'delete', assign: (e) => { ctx.selected = e.ids; ctx.error = null } }),
        on(Bulk, { target: 'archivingMany', guard: (e) => e.ids.length > 0 && e.action === 'archive', assign: (e) => { ctx.selected = e.ids; ctx.error = null } }),
        on(Bulk, { target: 'idle' }),
        on(Share, { target: 'sharing', assign: (e) => { ctx.target = e.id; ctx.shareName = e.name; ctx.error = null } }),
        on(Unshare, { target: 'unsharing', assign: (e) => { ctx.target = e.id; ctx.shareName = e.name; ctx.error = null } }),
        on(Restore, { target: 'restoring', assign: (e) => { ctx.target = e.id; ctx.error = null } }),
        on(Undo, { target: 'undoing', assign: (e) => { ctx.target = e.id; ctx.error = null } }),
        on(Search, { target: 'idle', assign: (e) => { ctx.q = e.q } }),
        on(Edit, { target: 'idle', assign: (e) => { ctx.editing = e.id; ctx.editError = null } }),
        on(CancelEdit, { target: 'idle', assign: () => { ctx.editing = ''; ctx.editError = null } }),
        on(Save, {
          target: 'saving',
          assign: (e) => {
            ctx.editing = e.id
            ctx.editTitle = e.title
            ctx.editError = null
            ctx.error = null
          },
        }),
      ],
    },
    adding: {
      invoke: invoke(addNote, {
        input: { title: ctx.draft },
        done: { target: 'idle', assign: () => { ctx.draft = '' } },
        failed: {
          Duplicate: { target: 'idle', assign: () => { ctx.error = DUPLICATE } },
          TooMany: { target: 'idle', assign: () => { ctx.error = TOO_MANY } },
          Invalid: { target: 'idle', assign: (e) => { ctx.fields = e.fields } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    saving: {
      invoke: invoke(renameNote, {
        input: { id: ctx.editing, title: ctx.editTitle },
        done: { target: 'idle', assign: () => { ctx.editing = ''; ctx.editTitle = '' } },
        failed: {
          Duplicate: { target: 'idle', assign: () => { ctx.editError = DUPLICATE } },
          NotFound: { target: 'idle', assign: () => { ctx.editing = ''; ctx.error = NOT_FOUND } },
          Archived: { target: 'idle', assign: () => { ctx.editing = ''; ctx.error = ARCHIVED } },
          Invalid: { target: 'idle', assign: (e) => { ctx.editError = e.fields.title } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.editError = e.message } },
        },
      }),
    },
    removing: {
      invoke: invoke(removeNote, {
        input: { id: ctx.target },
        done: 'idle',
        failed: {
          NotFound: { target: 'idle', assign: () => { ctx.error = NOT_FOUND } },
          Archived: { target: 'idle', assign: () => { ctx.error = ARCHIVED } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    pinning: {
      invoke: invoke(togglePin, {
        input: { id: ctx.target },
        done: 'idle',
        failed: {
          NotFound: { target: 'idle', assign: () => { ctx.error = NOT_FOUND } },
          Archived: { target: 'idle', assign: () => { ctx.error = ARCHIVED } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    archiving: {
      invoke: invoke(archiveNote, {
        input: { id: ctx.target },
        done: 'idle',
        failed: {
          NotFound: { target: 'idle', assign: () => { ctx.error = NOT_FOUND } },
          Archived: { target: 'idle', assign: () => { ctx.error = ARCHIVED } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    sharing: {
      invoke: invoke(shareNote, {
        input: { id: ctx.target, name: ctx.shareName },
        done: { target: 'idle', assign: () => { ctx.shareName = '' } },
        failed: {
          NotFound: { target: 'idle', assign: () => { ctx.error = NOT_FOUND } },
          Archived: { target: 'idle', assign: () => { ctx.error = ARCHIVED } },
          Self: { target: 'idle', assign: () => { ctx.error = SHARE_SELF } },
          Invalid: { target: 'idle', assign: (e) => { ctx.error = e.fields.name } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    unsharing: {
      invoke: invoke(unshareNote, {
        input: { id: ctx.target, name: ctx.shareName },
        done: { target: 'idle', assign: () => { ctx.shareName = '' } },
        failed: {
          NotFound: { target: 'idle', assign: () => { ctx.error = NOT_FOUND } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    restoring: {
      invoke: invoke(restoreNote, {
        input: { id: ctx.target },
        done: 'idle',
        failed: {
          NotFound: { target: 'idle', assign: () => { ctx.error = NOT_FOUND } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    removingMany: {
      invoke: invoke(removeNotes, {
        input: { ids: ctx.selected },
        done: { target: 'idle', assign: () => { ctx.selected = [] } },
        failed: {
          Invalid: { target: 'idle', assign: (e) => { ctx.selected = []; ctx.error = e.message } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    archivingMany: {
      invoke: invoke(archiveNotes, {
        input: { ids: ctx.selected },
        done: { target: 'idle', assign: () => { ctx.selected = [] } },
        failed: {
          Invalid: { target: 'idle', assign: (e) => { ctx.selected = []; ctx.error = e.message } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    undoing: {
      invoke: invoke(undoRemove, {
        input: { id: ctx.target },
        done: 'idle',
        failed: {
          NotFound: { target: 'idle', assign: () => { ctx.error = NOTHING_TO_UNDO } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
  }),
})
import { contract, part, ui } from '@hozu/core'
import { accountDelete, archive, home, notePage } from '../../routes.ts'
import {
  Add,
  Archive,
  archiveNotes,
  Bulk,
  removeNotes,
  Select,
  listArchived,
  getNote,
  Restore,
  addedOn,
  exportNotes,
  CancelEdit,
  Edit,
  Save,
  Draft,
  listNotes,
  matching,
  firstMatching,
  countMatching,
  noneMatch,
  notesMachine,
  Pin,
  Remove,
  Search,
  Undo,
  lastDeleted,
  listShared,
  Share,
  Unshare,
  DUPLICATE,
} from './model.ts'

export const notesText = ui.messages('en', {
  en: { notes: 'Notes', count: 'Notes: {count}', title: 'Title', add: 'Add', delete: 'Delete', search: 'Search', duplicate: 'You already have a note with this title' },
  de: { notes: 'Notizen', count: 'Notizen: {count}', title: 'Titel', add: 'Hinzufügen', delete: 'Löschen', search: 'Suche', duplicate: 'Du hast bereits eine Notiz mit diesem Titel' },
})

// The note being added, shown first until the server accepts it.
const pendingNote = part((title: string) =>
  ui.li({ class: 'flex items-center gap-3 px-4 py-3 opacity-50', 'aria-busy': 'true' }, [
    ui.span({ class: 'flex-1' }, [title]),
    ui.span({ class: 'text-xs text-slate-500' }, ['saving']),
  ]),
)

// The bulk buttons; each note's checkbox joins this form.
const bulk = ui.formRef()

export const NotesBoard = ui.view({
  machine: notesMachine,
  route: home,
  seed: ({ search }) => ({ q: search.q }),
  render: ({ ctx, when, search, locale }) =>
    ui.main({ class: 'mx-auto max-w-xl space-y-6 px-4 py-12' }, [
      ui.h1({ class: 'text-3xl font-bold' }, [notesText.notes]),
      ui.nav({ class: 'flex gap-4 text-sm' }, [
        ui.a({ href: locale === 'en' ? ui.alternate('de') : ui.alternate('en'), class: 'underline' }, [locale === 'en' ? 'Deutsch' : 'English']),
        ui.a({ href: ui.link(archive, null), class: 'underline' }, ['Archived notes']),
        ui.a({ href: ui.link(accountDelete, null), class: 'underline' }, ['Delete account']),
        ui.a({ href: ui.link(exportNotes, {}), class: 'underline' }, ['Export']),
      ]),
      ui.form({ class: 'flex gap-2', on: { submit: ui.send(Add, { title: ui.dom.form('title') }) } }, [
        ui.label({ for: 'notes-title', class: 'sr-only' }, [notesText.title]),
        ui.input({
          id: 'notes-title',
          name: 'title',
          required: true,
          maxlength: 60,
          placeholder: notesText.title,
          value: ctx.draft,
          'aria-invalid': ctx.fields.title !== null,
          'aria-describedby': 'notes-title-error',
          class: 'flex-1 rounded border px-3 py-2',
          on: { input: ui.send(Draft, { title: ui.dom.value }) },
        }),
        ui.button({ type: 'submit', class: 'rounded bg-indigo-600 px-4 py-2 text-white' }, [notesText.add]),
      ]),
      ui.p({ id: 'notes-title-error', role: 'alert', class: 'text-sm text-rose-600' }, [ctx.fields.title]),
      ctx.error !== null && ui.p({ role: 'alert', class: 'text-rose-600' }, [ctx.error === DUPLICATE ? notesText.duplicate : ctx.error]),
      ui.query(
        lastDeleted,
        {},
        {
          ready: (deleted) =>
            deleted === null
              ? null
              : ui.div({ role: 'status', class: 'flex items-center gap-3 rounded bg-slate-100 px-4 py-2 text-sm' }, [
                ui.span({ class: 'flex-1' }, [`Deleted "${deleted.title}"`]),
                ui.form({ class: 'inline', on: { submit: ui.send(Undo, { id: ui.dom.form('id') }) } }, [
                  ui.input({ type: 'hidden', name: 'id', value: deleted.id }),
                  ui.button({ type: 'submit', class: 'underline' }, ['Undo']),
                ]),
              ]),
          failed: { Unauthorized: () => null, Unexpected: () => null },
        },
      ),
      ui.query(
        listNotes,
        {},
        {
          ready: (items) => ui.div({ class: 'space-y-3' }, [
            ui.p({ class: 'text-sm text-slate-600' }, [notesText.count({ count: items.length })]),
            ui.form({ method: 'get', class: 'flex gap-2' }, [
              ui.input({
                type: 'search',
                name: 'q',
                'aria-label': notesText.search,
                placeholder: notesText.search,
                value: ctx.q,
                class: 'flex-1 rounded border px-3 py-2',
                on: { input: ui.send(Search, { q: ui.dom.value }) },
              }),
              ui.button({ type: 'submit', class: 'rounded border px-4 py-2' }, [notesText.search]),
            ]),
            ui.p({ class: 'text-sm text-slate-600' }, [
              `Showing ${matching({ items: firstMatching({ items, q: search.q, limit: search.limit }), q: ctx.q }).length} of ${countMatching({ items, q: search.q })}`,
            ]),
            ui.form({ ref: bulk, 'aria-label': 'Bulk actions', class: 'flex items-center gap-3 text-sm', on: { submit: ui.send(Bulk, { ids: ui.dom.formAll('ids'), action: ui.dom.form('action') }) } }, [
              ui.span({ class: 'flex-1 text-slate-600' }, [`Selected: ${ctx.selected.length}`]),
              ui.button({ type: 'submit', name: 'action', value: 'delete', class: 'rounded border px-3 py-1' }, ['Delete selected']),
              ui.button({ type: 'submit', name: 'action', value: 'archive', class: 'rounded border px-3 py-1' }, ['Archive selected']),
            ]),
            noneMatch({ items: firstMatching({ items, q: search.q, limit: search.limit }), q: ctx.q })
              ? [
                when(['adding'], [ui.ul({ class: 'divide-y rounded border bg-white' }, [pendingNote(ctx.draft)])]),
                ui.p({ class: 'text-slate-500' }, ['No notes match']),
              ]
              : ui.ul({ class: 'divide-y rounded border bg-white' }, [
                when(['adding'], [pendingNote(ctx.draft)]),
                ui.each(matching({ items: firstMatching({ items, q: search.q, limit: search.limit }), q: ctx.q }), 'id', (item) =>
                  ui.li({ class: 'flex items-center gap-3 px-4 py-3' }, [
                    ui.input({
                      type: 'checkbox',
                      form: bulk,
                      name: 'ids',
                      value: item.id,
                      'aria-label': `Select ${item.title}`,
                      checked: ctx.selected.includes(item.id),
                      on: { change: ui.send(Select, { id: item.id, checked: ui.dom.checked }) },
                    }),
                    ctx.editing === item.id
                      ? ui.form({ class: 'flex flex-1 flex-wrap items-center gap-2', on: { submit: ui.send(Save, { id: ui.dom.form('id'), title: ui.dom.form('title') }) } }, [
                        ui.input({ type: 'hidden', name: 'id', value: item.id }),
                        ui.input({
                          name: 'title',
                          'aria-label': 'Edit title',
                          required: true,
                          maxlength: 60,
                          value: item.title,
                          'aria-invalid': ctx.editError !== null,
                          class: 'flex-1 rounded border px-2 py-1',
                        }),
                        ui.button({ type: 'submit', class: 'text-sm underline' }, ['Save']),
                        ctx.editError !== null && ui.p({ role: 'alert', class: 'w-full text-sm text-rose-600' }, [ctx.editError === DUPLICATE ? notesText.duplicate : ctx.editError]),
                      ])
                      : ui.a({ href: ui.link(notePage, { number: `${item.number}` }), class: 'flex-1 underline' }, [item.title]),
                    ui.span({ class: 'text-xs text-slate-500' }, [`No. ${item.number}`]),
                    ui.time({ datetime: item.createdAt, class: 'text-xs text-slate-500' }, [`Added ${addedOn({ at: item.createdAt })}`]),
                    item.pinned && ui.span({ class: 'rounded bg-amber-100 px-2 text-xs text-amber-800' }, ['pinned']),
                    ui.form({ class: 'inline', on: { submit: ui.send(Pin, { id: ui.dom.form('id') }) } }, [
                      ui.input({ type: 'hidden', name: 'id', value: item.id }),
                      ui.button({ type: 'submit', class: 'text-sm underline' }, [item.pinned ? 'Unpin' : 'Pin']),
                    ]),
                    ctx.editing === item.id
                      ? ui.form({ class: 'inline', on: { submit: ui.send(CancelEdit, {}) } }, [
                        ui.button({ type: 'submit', class: 'text-sm underline' }, ['Cancel']),
                      ])
                      : ui.form({ class: 'inline', on: { submit: ui.send(Edit, { id: ui.dom.form('id') }) } }, [
                        ui.input({ type: 'hidden', name: 'id', value: item.id }),
                        ui.button({ type: 'submit', class: 'text-sm underline' }, ['Edit']),
                      ]),
                    ui.form({ class: 'inline', on: { submit: ui.send(Remove, { id: ui.dom.form('id') }) } }, [
                      ui.input({ type: 'hidden', name: 'id', value: item.id }),
                      ui.button({ type: 'submit', class: 'text-sm underline' }, [notesText.delete]),
                    ]),
                    ui.form({ class: 'inline', on: { submit: ui.send(Archive, { id: ui.dom.form('id') }) } }, [
                      ui.input({ type: 'hidden', name: 'id', value: item.id }),
                      ui.button({ type: 'submit', class: 'text-sm underline' }, ['Archive']),
                    ]),
                    ui.each(item.sharedWith, null, (name) =>
                      ui.span({ class: 'flex items-center gap-1 text-xs text-slate-500' }, [
                        `shared with ${name}`,
                      ui.form({ class: 'inline', on: { submit: ui.send(Unshare, { id: ui.dom.form('id'), name: ui.dom.form('name') }) } }, [
                        ui.input({ type: 'hidden', name: 'id', value: item.id }),
                        ui.input({ type: 'hidden', name: 'name', value: name }),
                          ui.button({ type: 'submit', class: 'text-sm underline' }, [`Unshare ${name}`]),
                        ]),
                      ]),
                    ),
                    ui.form({ class: 'flex gap-1', on: { submit: ui.send(Share, { id: ui.dom.form('id'), name: ui.dom.form('name') }) } }, [
                      ui.input({ type: 'hidden', name: 'id', value: item.id }),
                      ui.input({ name: 'name', 'aria-label': 'Share with', required: true, maxlength: 20, class: 'w-24 rounded border px-2 py-1 text-sm' }),
                      ui.button({ type: 'submit', class: 'text-sm underline' }, ['Share']),
                    ]),
                  ]),
                ),
              ]),
            countMatching({ items, q: search.q }) > search.limit &&
              ui.a({ href: ui.link(home, null, { q: search.q, limit: search.limit + 5 }), class: 'inline-block rounded border px-4 py-2 text-sm' }, ['Load more']),
          ]),
          pending: ui.p({}, ['Loading…']),
          failed: { Unauthorized: () => ui.p({ role: 'alert' }, ['Signed out']), Unexpected: () => ui.p({ role: 'alert' }, ['Unavailable']) },
        },
      ),
      ui.query(
        listShared,
        {},
        {
          ready: (shared) =>
            shared.length === 0
              ? null
              : ui.section({ class: 'space-y-3' }, [
                ui.h2({ class: 'text-xl font-semibold' }, ['Shared with me']),
                ui.ul({ class: 'divide-y rounded border bg-white' }, [
                  ui.each(shared, 'id', (note) =>
                    ui.li({ class: 'flex items-center gap-3 px-4 py-3' }, [
                      ui.span({ class: 'flex-1' }, [note.title]),
                      ui.span({ class: 'text-xs text-slate-500' }, [`from ${note.owner}`]),
                    ]),
                  ),
                ]),
              ]),
          failed: { Unauthorized: () => null, Unexpected: () => null },
        },
      ),
    ]),
})

export const ArchiveBoard = ui.view({
  machine: notesMachine,
  route: archive,
  render: ({ ctx }) =>
    ui.main({ class: 'mx-auto max-w-xl space-y-6 px-4 py-12' }, [
      ui.h1({ class: 'text-3xl font-bold' }, ['Archive']),
      ui.a({ href: ui.link(home, null), class: 'text-sm underline' }, ['All notes']),
      ctx.error !== null && ui.p({ role: 'alert', class: 'text-rose-600' }, [ctx.error]),
      ui.query(
        listArchived,
        {},
        {
          ready: (items) =>
            items.length === 0
              ? ui.p({ class: 'text-slate-500' }, ['No archived notes'])
              : ui.ul({ class: 'divide-y rounded border bg-white' }, [
                ui.each(items, 'id', (item) =>
                  ui.li({ class: 'flex items-center gap-3 px-4 py-3' }, [
                    ui.a({ href: ui.link(notePage, { number: `${item.number}` }), class: 'flex-1 underline' }, [item.title]),
                    ui.form({ class: 'inline', on: { submit: ui.send(Restore, { id: ui.dom.form('id') }) } }, [
                      ui.input({ type: 'hidden', name: 'id', value: item.id }),
                      ui.button({ type: 'submit', class: 'text-sm underline' }, ['Restore']),
                    ]),
                  ]),
                ),
              ]),
          pending: ui.p({}, ['Loading…']),
          failed: { Unauthorized: () => ui.p({ role: 'alert' }, ['Signed out']), Unexpected: () => ui.p({ role: 'alert' }, ['Unavailable']) },
        },
      ),
    ]),
})

// One note of the signed-in user, by its number.
export const NoteDetailPage = ui.view({
  route: notePage,
  render: ({ params }) =>
    ui.main({ class: 'mx-auto max-w-xl space-y-4 px-4 py-12' }, [
      ui.a({ href: ui.link(home, null), class: 'text-sm underline' }, ['Back to notes']),
      ui.query(
        getNote,
        { number: params.number },
        {
          ready: (note) =>
            ui.article({ class: 'space-y-2' }, [
              ui.h1({ class: 'text-3xl font-bold' }, [note.title]),
              ui.p({ class: 'flex gap-3 text-sm text-slate-500' }, [
                ui.span({}, [`No. ${note.number}`]),
                ui.time({ datetime: note.createdAt }, [`Added ${addedOn({ at: note.createdAt })}`]),
                note.pinned && ui.span({ class: 'rounded bg-amber-100 px-2 text-xs text-amber-800' }, ['pinned']),
                note.archived && ui.span({ class: 'rounded bg-slate-200 px-2 text-xs text-slate-700' }, ['Archived']),
              ])

