import { resolvers } from '@hozu/data'
import { app } from '@hozu/runtime-server'
import project from './hozu.config.ts'
import { createNumbers, createStore, notesResolvers, ownedCounts, type Deleted } from './features/notes/server.ts'
import { adminResolvers } from './features/admin/server.ts'
import { accountResolvers } from './features/account/server.ts'

// Undo of the last delete, per user; signing out forgets it.
const deleted: Deleted = new Map()
const store = createStore()
// Per user: the highest note number given out so far.
const numbers = createNumbers()
// Everyone who has signed in, for the admin page.
const seen = new Set<string>()

export default app({
  resolvers: resolvers(project, (implement) => [
    ...accountResolvers(
      implement,
      (user) => deleted.delete(user),
      (user) => seen.add(user),
      // Deleting an account drops the user's notes (shared ones vanish for their recipients) and forgets the user.
      (user) => {
        store.delete(user)
        numbers.delete(user)
        deleted.delete(user)
        seen.delete(user)
      },
    ),
    ...notesResolvers(implement, deleted, store, numbers),
    ...adminResolvers(implement, () => ownedCounts(store), seen),
  ]),
})
import { project, ui } from '@hozu/core'
import { zodAdapter } from '@hozu/schema-zod'
import { accountDelete, admin, archive, home, login, notePage } from './routes.ts'
import { AdminBoard, AdminLink } from './features/admin/views.ts'
import { listUsers } from './features/admin/model.ts'
import { adminFeature } from './features/admin/feature.ts'
import { ArchiveBoard, NoteDetailPage, NotesBoard, notesText } from './features/notes/views.ts'
import { notes } from './features/notes/feature.ts'
import { getNote } from './features/notes/model.ts'
import { me, Session } from './features/account/model.ts'
import { AccountBar, accountText, DeleteAccountPage, Login } from './features/account/views.ts'
import { account } from './features/account/feature.ts'

export default project({
  schema: zodAdapter,
  session: Session,
  styles: new URL('./app.css', import.meta.url),
  app: new URL('./app.ts', import.meta.url),
  env: { files: ['.env', '.env.local'] },
  site: { url: 'http://localhost:3000', name: 'app', lang: 'en', locales: ['en', 'de'] },
  routes: { home, login, archive, admin, accountDelete, notePage },
  pages: [
    ui.page(login, { views: [Login], head: { render: () => ({ title: accountText.signIn }) } }),
    ui.page(home, {
      views: [AccountBar, AdminLink, NotesBoard],
      head: {
        query: me,
        input: () => ({}),
        render: () => ({ title: notesText.notes, noindex: true }),
        failed: { Unauthorized: login },
      },
    }),
    ui.page(archive, {
      views: [AccountBar, ArchiveBoard],
      head: {
        query: me,
        input: () => ({}),
        render: () => ({ title: 'Archive', noindex: true }),
        failed: { Unauthorized: login },
      },
    }),
    ui.page(notePage, {
      views: [AccountBar, NoteDetailPage],
      head: {
        query: getNote,
        input: (params) => ({ number: params.number }),
        render: (note) => ({ title: note.title, noindex: true }),
        failed: { Unauthorized: login, NotFound: 404 },
      },
    }),
    ui.page(accountDelete, {
      views: [DeleteAccountPage],
      head: {
        query: me,
        input: () => ({}),
        render: () => ({ title: 'Delete account', noindex: true }),
        failed: { Unauthorized: login },
      },
    }),
    ui.page(admin, {
      views: [AccountBar, AdminBoard],
      head: {
        query: listUsers,
        input: () => ({}),
        render: () => ({ title: 'Admin', noindex: true }),
        failed: { Unauthorized: login, Forbidden: 403 },
      },
    })],
  features: [account, notes, adminFeature],
})
import { route } from '@hozu/core'
import { z } from 'zod'

export const home = route({ path: '/notes', params: null, search: z.object({ q: z.string().default(''), limit: z.number().int().min(1).default(5) }) })
export const login = route({ path: '/login', params: null, search: z.object({ deleted: z.boolean().default(false) }) })
export const archive = route({ path: '/archive', params: null, search: null })
export const admin = route({ path: '/admin', params: null, search: null })
export const accountDelete = route({ path: '/account/delete', params: null, search: null })
// One of the signed-in user's own notes, by its number; a number that is not a number is a 404.
export const notePage = route({ path: '/notes/:number', params: z.object({ number: z.string() }), search: null })

